package main

import (
	"crypto/hmac"
	"crypto/sha256"
	"encoding/hex"
	"fmt"
	"sync"
	"time"
)

type CircuitState int

const (
	Closed CircuitState = iota
	Open
	HalfOpen
)

type CircuitBreaker struct {
	mu           sync.RWMutex
	state        CircuitState
	failures     int
	threshold    int
	resetTimeout time.Duration
	lastFailure  time.Time
}

func NewCircuitBreaker(threshold int, timeout time.Duration) *CircuitBreaker {
	return &CircuitBreaker{
		state:        Closed,
		threshold:    threshold,
		resetTimeout: timeout,
	}
}

func (cb *CircuitBreaker) Allow() bool {
	cb.mu.RLock()
	defer cb.mu.RUnlock()
	switch cb.state {
	case Open:
		if time.Since(cb.lastFailure) > cb.resetTimeout {
			return true
		}
		return false
	case HalfOpen:
		return true
	default:
		return true
	}
}

func (cb *CircuitBreaker) RecordSuccess() {
	cb.mu.Lock()
	defer cb.mu.Unlock()
	cb.failures = 0
	cb.state = Closed
}

func (cb *CircuitBreaker) RecordFailure() {
	cb.mu.Lock()
	defer cb.mu.Unlock()
	cb.failures++
	cb.lastFailure = time.Now()
	if cb.failures >= cb.threshold {
		cb.state = Open
	}
}

type Message struct {
	ID        string
	Payload   []byte
	Timestamp int64
	Signature string
}

type NonceStore struct {
	mu     sync.RWMutex
	nonces map[string]int64
	ttl    time.Duration
}

func NewNonceStore(ttl time.Duration) *NonceStore {
	ns := &NonceStore{
		nonces: make(map[string]int64),
		ttl:    ttl,
	}
	go ns.cleanup()
	return ns
}

func (ns *NonceStore) cleanup() {
	ticker := time.NewTicker(ns.ttl / 2)
	for range ticker.C {
		ns.mu.Lock()
		now := time.Now().Unix()
		for k, v := range ns.nonces {
			if now-v > int64(ns.ttl.Seconds()) {
				delete(ns.nonces, k)
			}
		}
		ns.mu.Unlock()
	}
}

func (ns *NonceStore) CheckAndStore(nonce string, timestamp int64) bool {
	ns.mu.Lock()
	defer ns.mu.Unlock()
	if _, exists := ns.nonces[nonce]; exists {
		return false
	}
	ns.nonces[nonce] = timestamp
	return true
}

type Consumer struct {
	cb         *CircuitBreaker
	nonceStore *NonceStore
	secretKey  []byte
	maxAge     time.Duration
}

func NewConsumer(secret []byte) *Consumer {
	return &Consumer{
		cb:         NewCircuitBreaker(5, 30*time.Second),
		nonceStore: NewNonceStore(5 * time.Minute),
		secretKey:  secret,
		maxAge:     5 * time.Minute,
	}
}

func (c *Consumer) verifySignature(msg *Message) bool {
	mac := hmac.New(sha256.New, c.secretKey)
	mac.Write([]byte(msg.ID))
	mac.Write(msg.Payload)
	tsBuf := fmt.Sprintf("%d", msg.Timestamp)
	mac.Write([]byte(tsBuf))
	expected := hex.EncodeToString(mac.Sum(nil))
	return hmac.Equal([]byte(expected), []byte(msg.Signature))
}

func (c *Consumer) validateTimestamp(msg *Message) bool {
	msgTime := time.Unix(msg.Timestamp, 0)
	return time.Since(msgTime) <= c.maxAge
}

func (c *Consumer) ProcessMessage(msg *Message) error {
	if !c.cb.Allow() {
		return fmt.Errorf("circuit breaker open, rejecting message %s", msg.ID)
	}

	if !c.verifySignature(msg) {
		c.cb.RecordFailure()
		return fmt.Errorf("invalid signature for message %s", msg.ID)
	}

	if !c.validateTimestamp(msg) {
		c.cb.RecordFailure()
		return fmt.Errorf("message %s timestamp expired", msg.ID)
	}

	if !c.nonceStore.CheckAndStore(msg.Signature, msg.Timestamp) {
		return fmt.Errorf("duplicate message %s rejected", msg.ID)
	}

	c.cb.RecordSuccess()
	return c.handleMessage(msg)
}

func (c *Consumer) handleMessage(msg *Message) error {
	fmt.Printf("Processing message %s: %s\n", msg.ID, string(msg.Payload))
	return nil
}

func main() {
	secret := []byte("super-secret-key-2024")
	consumer := NewConsumer(secret)

	msg := &Message{
		ID:        "msg-001",
		Payload:   []byte("transfer $1000"),
		Timestamp: time.Now().Unix(),
	}

	mac := hmac.New(sha256.New, secret)
	mac.Write([]byte(msg.ID))
	mac.Write(msg.Payload)
	mac.Write([]byte(fmt.Sprintf("%d", msg.Timestamp)))
	msg.Signature = hex.EncodeToString(mac.Sum(nil))

	err := consumer.ProcessMessage(msg)
	if err != nil {
		fmt.Printf("Error: %v\n", err)
	}
}
